+                            .map(s -> s.replaceAll(request.renamePattern(), request.renameReplacement()))
+                            .collect(Collectors.toList());
+                        return new DataStreamAlias(alias.getName(), renamedDataStreams);
+                    } else {
+                        return alias;
+                    }
